from collections import deque
s='''000000000000000000000000000000
000000000000000000000000011111
000000000000000000000000010001
000000000000000000000000010001
000001111100000000111000110001
000001000111000000101000100001
000001000001000000101000111111
000001000001000000111000000000
000001111000000000000000000000
000000001000000000000000000000
000000001111000000000000000000
000000000000000000000111111000
000000000000000000000100001000
000000000000000000000100001000
000000000000000000000100001000
000000000000000000000100001000
000000001111111110000111101000
000000001000000010000000000000
000000001000000000000000000000
000000001000000010000000000000
000000001000000000000000000000
000000001111000010000000000000
000000000001000010000011111000
000000000001000010000010000100
000000000001111110000011001100
000000000000000000000001000100
000000000000000000000001111100
000000000000000000000000000000
000000000000000000000000000000
000000000000000000000000000000'''
g=[list(map(int,r)) for r in s.splitlines()];R=C=30
# zero comps 4-connected
zl={};zc=[]
for r in range(R):
 for c in range(C):
  if not g[r][c] and (r,c) not in zl:
   i=len(zc);zl[r,c]=i;q=deque([(r,c)]);cells=[];edge=False
   while q:
    x,y=q.popleft();cells.append((x,y));edge|=x in (0,R-1) or y in (0,C-1)
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and g[nx][ny]==0 and (nx,ny) not in zl:zl[nx,ny]=i;q.append((nx,ny))
   zc.append((edge,cells))
closed={i for i,(e,cells) in enumerate(zc) if not e}
# 1 comp 4-connected; collect components adjacent orthogonally to enclosed hole
ol={};oc=[]
for r in range(R):
 for c in range(C):
  if g[r][c] and (r,c) not in ol:
   i=len(oc);ol[r,c]=i;q=deque([(r,c)]);cells=[]
   while q:
    x,y=q.popleft();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and g[nx][ny]==1 and (nx,ny) not in ol:ol[nx,ny]=i;q.append((nx,ny))
   oc.append(cells)
out=[row[:] for row in g]
qual=set()
for i in closed:
 cells=zc[i][1]
 for x,y in cells:
  for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
   nx,ny=x+dx,y+dy
   if 0<=nx<R and 0<=ny<C and g[nx][ny]==1:qual.add(ol[nx,ny])
# inner zeros 8-adjacent to 1 of qualifying components
for i in closed:
 for x,y in zc[i][1]:
  if any(0<=x+dx<R and 0<=y+dy<C and g[x+dx][y+dy]==1 and ol[x+dx,y+dy] in qual for dx in (-1,0,1) for dy in (-1,0,1) if dx or dy):out[x][y]=3
# exterior halo 8 neighbor of entire qualifying 1-component
for j in qual:
 for x,y in oc[j]:
  for dx in (-1,0,1):
   for dy in (-1,0,1):
    nx,ny=x+dx,y+dy
    if 0<=nx<R and 0<=ny<C and g[nx][ny]==0 and zl[nx,ny] not in closed:out[nx][ny]=2
print('qual',qual,'closed',closed)
for row in out: print(' '.join(map(str,row)))

